=== A. driver skeleton (POSIX sh) ===
```sh
#!/bin/sh
set -eu
FORGE=~/.foundry/bin/forge
NPROC=$(nproc)                       # 20 on the measured box, NOT 32
S=$1; W=$(mktemp -d)
mkdir -p "$W/src" "$W/test"; cp "$S" "$W/src/Target.sol"
cat > "$W/foundry.toml" <<'EOF'
[profile.default]
src='src'
test='test'
out='out'
solc='0.8.24'
EOF
# --- phase 0: facts
(cd "$W" && $FORGE build -q \
 && $FORGE inspect Target storageLayout    --json > layout.json \
 && $FORGE inspect Target methodIdentifiers --json > mids.json \
 && $FORGE inspect Target abi              --json > abi.json \
 && FOUNDRY_AST=true $FORGE build --build-info --force -q)
python3 tools/ast_offsets.py "$W"/out/build-info/*.json > "$W/nodes.json"   # src="off:len:fid"
# --- phase 1: permission fingerprint (zero LLM)
python3 tools/gen_fingerprint.py "$W"
(cd "$W" && $FORGE test --match-contract FP --json > fp.json) || true
python3 tools/parse_fp.py "$W" > "$W/perm.json"
# --- phase 2: honest-best escalation (fuzzer used as an optimiser)
python3 tools/gen_honest.py "$W"
i=0; while [ $i -lt 6 ]; do
  seq 1 "$NPROC" | xargs -P "$NPROC" -I{} sh -c \
    "cd $W && $FORGE test --match-test testFuzz_honest --fuzz-seed {} --fuzz-runs 20000 --json > hs_{}.json 2>&1" || true
  python3 tools/raise_best.py "$W" || break        # exit 1 == converged
  i=$((i+1))
done
# --- phase 3/4: candidates -> four worlds
ls -d "$W"/cand/*/ | xargs -P "$NPROC" -I{} sh -c "cd {} && $FORGE build -q 2>build.err || true"
ls -d "$W"/cand/*/ | xargs -P "$NPROC" -I{} sh -c "cd {} && python3 $PWD/tools/bytecode_gate.py . || exit 0"
ls -d "$W"/cand/*/ | xargs -P "$NPROC" -I{} sh -c \
  "cd {} && $FORGE test --match-contract Judge --fuzz-runs 2000 --json > run.json 2>&1 || true"
# --- phase 5: canaries, reusing the SAME portfolio, zero requests
python3 tools/splice_canaries.py "$W" "$W/nodes.json"
ls -d "$W"/canary/*/cand/*/ | xargs -P "$NPROC" -I{} sh -c \
  "cd {} && $FORGE test --match-contract Judge --fuzz-runs 256 --json > run.json 2>&1 || true"
python3 tools/verdict.py "$W"        # VULNERABLE | SAFE | UNRESOLVED(->VULNERABLE)
```

=== B. Judge.t.sol — 100% harness-owned. The generator emits zero bytes into this file. ===
```solidity
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import {Target}   from "../src/Target.sol";
import {Attacker} from "../src/Attacker.sol";   // ONLY file with generated content
import {Honest}   from "../src/Honest.sol";     // ABI-derived, harness-generated

interface Vm {
    function deal(address,uint256) external;
    function prank(address) external;
    function load(address,bytes32) external view returns (bytes32);
    function record() external;
    function accesses(address) external returns (bytes32[] memory, bytes32[] memory);
    function warp(uint256) external;
    function snapshotState() external returns (uint256);
    function revertToState(uint256) external returns (bool);
}

contract Judge {
    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    uint256 constant E = 100 ether;              // identical endowment, every actor
    address constant OWNER = address(0xD00D);
    address constant ATT   = address(0xA11CE);
    address constant HON   = address(0xB0B);
    address constant HON2  = address(0xCAFE);

    function _bs() internal pure returns (uint256[] memory s) { s = /*__BALSLOTS__*/; }
    function _bestProg() internal pure returns (bytes memory) { return hex"/*__BESTPROG__*/"; }

    Target t; Honest h; Attacker a;

    function setUp() public {
        vm.deal(OWNER,E); vm.deal(ATT,E); vm.deal(HON,E); vm.deal(HON2,E);
        vm.prank(OWNER);
        t = new Target();                        // canonical ctor args injected by driver
        h = new Honest(payable(address(t)));
        vm.deal(address(h), E);
    }

    // net worth is a VECTOR; no exchange rate is invented anywhere
    function _worth(address who) internal view returns (uint256[] memory v) {
        uint256[] memory s = _bs();
        v = new uint256[](s.length + 1);
        v[0] = who.balance;
        for (uint256 i; i < s.length; ++i)
            v[i+1] = uint256(vm.load(address(t), keccak256(abi.encode(who, s[i]))));
    }
    function _worth2(address x, address y) internal view returns (uint256[] memory v) {
        uint256[] memory p = _worth(x); uint256[] memory q = _worth(y);
        v = new uint256[](p.length);
        for (uint256 i; i < p.length; ++i) v[i] = p[i] + q[i];
    }
    function _dom(uint256[] memory x, uint256[] memory y) internal pure returns (bool st) {
        for (uint256 i; i < x.length; ++i) { if (x[i] < y[i]) return false; if (x[i] > y[i]) st = true; }
    }
    function _harm(uint256[] memory now_, uint256[] memory ref) internal pure returns (uint256 g) {
        for (uint256 i; i < ref.length; ++i) if (ref[i] > now_[i]) g += ref[i] - now_[i];
    }
    function _gap() internal view returns (uint256) {       // liabilities - assets, clamped
        uint256 L; uint256[] memory s = _bs();
        address[4] memory who = [ATT, HON, HON2, address(a)];
        for (uint256 j; j < 4; ++j)
            for (uint256 i; i < s.length; ++i)
                L += uint256(vm.load(address(t), keccak256(abi.encode(who[j], s[i]))));
        return L > address(t).balance ? L - address(t).balance : 0;
    }
    function _endow() internal pure returns (uint256[] memory v) {
        v = new uint256[](_bs().length + 1); v[0] = E;
    }

    // ---------- CHANNEL A. Test PASSES iff a finding. A revert means "no finding".
    function test_gateA() public {
        uint256 snap = vm.snapshotState();
        h.run(HON);                                        // ---- W0
        uint256[] memory H0 = _worth(HON);
        uint256 S0 = _gap();
        require(vm.revertToState(snap), "snap");
        snap = vm.snapshotState();

        a = new Attacker{value: E}(payable(address(t)));   // endowment is a harness constant
        vm.prank(ATT);
        a.attack();                                        // <-- the ONLY generated code
        h.run(HON);                                        // ---- W1
        uint256[] memory A1 = _worth2(address(a), ATT);
        uint256 hm1 = _harm(_worth(HON), H0);
        require(_dom(A1, _endow()), "no profit");
        require(hm1 > 0 || _gap() > S0, "no harm");

        require(vm.revertToState(snap), "snap2");          // ---- W2: best ordinary play
        _replayBest(ATT);
        h.run(HON);
        require(_harm(_worth(HON), H0) < hm1, "reproduced by ordinary play");
    }

    function _replayBest(address who) internal { /* driver-generated decoder; see D */ }
}
