=== D. HonestSearch.t.sol — fuzzer as optimiser via counterexample escalation ===
```solidity
contract HonestSearch is Judge {
    bytes4[] UNPRIV;                                  // injected from perm.json
    function _best() internal pure returns (uint256[] memory b) { b = /*__BEST__*/; }
    function _initU() internal { UNPRIV = /*__UNPRIV__*/; }

    function testFuzz_honest(bytes calldata prog) public {
        _initU();
        require(prog.length >= 42 && prog.length <= 512);
        address[4] memory ACT = [ATT,HON,HON2,OWNER];
        uint256 i;
        while (i + 42 <= prog.length) {
            bytes4  sel = UNPRIV[uint8(prog[i]) % UNPRIV.length];
            uint256 u   = uint256(bytes32(prog[i+1:i+33]));
            address ad  = ACT[uint8(prog[i+33]) % 4];
            uint256 val = uint64(bytes8(prog[i+34:i+42])) % (E / 8);
            vm.prank(HON2);
            (bool ok,) = address(t).call{value: val}(_pack(sel, u, ad));
            ok;                                        // reverts are no-ops, never failures
            i += 42;
        }
        require(!_dom(_worth(HON2), _best()), "HONEST_BEAT");   // failure => raise BEST, re-run
    }
    function _pack(bytes4 s, uint256 u, address ad) internal pure returns (bytes memory) {
        /*__ARITY_SWITCH__*/                           // generated from abi.json per selector
    }
}
