=== E. canary splicer (byte splice at AST offsets; no Solidity parser is written) ===
```python
# tools/splice_canaries.py — offsets verified live on this box: src == "offset:length:fileId"
import json, sys, shutil
root = sys.argv[1]
src   = open(f"{root}/src/Target.sol").read()
nodes = json.load(open(sys.argv[2]))          # flattened AST: nodeType, src, operator, name
def rng(n):
    o, l, _ = map(int, n["src"].split(":")); return o, o + l
muts = []
for n in nodes:
    o, e = rng(n)
    if n["nodeType"] == "ExpressionStatement" and src[o:o+7] == "require":
        muts.append(("del_require",  src[:o] + " "*(e-o) + src[e:]))
    if n["nodeType"] == "ModifierInvocation":
        muts.append(("del_modifier", src[:o] + " "*(e-o) + src[e:]))
    if n["nodeType"] == "ExpressionStatement" and any(k in src[o:e] for k in ("+=","-=","*=")):
        muts.append(("unchecked",    src[:o] + "unchecked{" + src[o:e] + "}" + src[e:]))
    if n["nodeType"] == "BinaryOperation" and n.get("operator") in ("<=", ">="):
        op = n["operator"]; k = src.find(op, o, e)
        if k > 0: muts.append(("offbyone", src[:k] + op[0] + " " + src[k+2:]))
    if n["nodeType"] == "Identifier" and n.get("name") == "msg" and src[o:o+10] == "msg.sender":
        muts.append(("txorigin",     src[:o] + "tx.origin" + src[o+10:]))
for i, (kind, text) in enumerate(muts[:12]):
    d = f"{root}/canary/{i}_{kind}"
    shutil.copytree(root, d, ignore=shutil.ignore_patterns("canary","out"))
    open(f"{d}/src/Target.sol", "w").write(text)      # non-compiling mutants dropped downstream
```

